# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_hours(self):
        self.assertEqual(
            rounded_labels([Span(540, 600)], 60),
            ["09:00-10:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                rounded_labels([Span(540, 600)], step)


if __name__ == "__main__":
    unittest.main()
